namespace sv_6f691511336c4073b42fc1739dcfe628.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// All interactive components in the same circuit share one instance.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme, string? accentColor = null)
    {
        var changed = false;

        if (_theme != theme)
        {
            _theme = theme;
            changed = true;
        }

        if (accentColor is not null && _accentColor != accentColor)
        {
            _accentColor = accentColor;
            changed = true;
        }

        if (changed) NotifyChanged();
    }

    /// <summary>
    /// Returns the CSS class to apply to the document root.
    /// </summary>
    public string CssClass => Theme switch
    {
        ThemeMode.Dark => "theme-dark",
        ThemeMode.Light => "theme-light",
        _ => "theme-system"
    };

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island embedded in the static layout.
   Because this has @rendermode InteractiveServer on the call-site,
   it lives inside the circuit and shares the scoped ThemeService. *@

@using sv_6f691511336c4073b42fc1739dcfe628.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" title="Current theme" style="--accent: @ThemeSvc.AccentColor;">
    <span class="theme-icon">@ThemeIcon</span>
    <span class="theme-label">@ThemeSvc.Theme</span>
    <span class="accent-dot" style="background-color: @ThemeSvc.AccentColor;"></span>
</span>

@code {
    private string ThemeIcon => ThemeSvc.Theme switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

.theme-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.25rem 0.75rem;
    border-radius: 1rem;
    background-color: #e9ecef;
    font-size: 0.85rem;
}

.theme-icon {
    font-size: 1rem;
}

.accent-dot {
    display: inline-block;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 1px solid rgba(0,0,0,0.15);
}

@* Reusable interactive toggle — can be placed anywhere (sidebar, page, etc.). *@

@using sv_6f691511336c4073b42fc1739dcfe628.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary theme-toggle" @onclick="CycleTheme"
        title="Toggle theme: @ThemeSvc.Theme">
    @ThemeIcon @ThemeSvc.Theme
</button>

@code {
    private static readonly ThemeMode[] Modes = [ThemeMode.Light, ThemeMode.Dark, ThemeMode.System];

    private string ThemeIcon => ThemeSvc.Theme switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        var idx = (Array.IndexOf(Modes, ThemeSvc.Theme) + 1) % Modes.Length;
        ThemeSvc.Theme = Modes[idx];
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer

@using sv_6f691511336c4073b42fc1739dcfe628.Services
@inject ThemeService ThemeSvc
