namespace sv_6f691511336c4073b42fc1739dcfe628.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// All interactive components in the same circuit share one instance.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme, string? accentColor = null)
    {
        var changed = false;

        if (_theme != theme)
        {
            _theme = theme;
            changed = true;
        }

        if (accentColor is not null && _accentColor != accentColor)
        {
            _accentColor = accentColor;
            changed = true;
        }

        if (changed) NotifyChanged();
    }

    /// <summary>
    /// Returns the CSS class to apply to the document root.
    /// </summary>
    public string CssClass => Theme switch
    {
        ThemeMode.Dark => "theme-dark",
        ThemeMode.Light => "theme-light",
        _ => "theme-system"
    };

    private void NotifyChanged() => OnChange?.Invoke();
}

