toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer

@using sv_6f691511336c4073b42fc1739dcfe628.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <div class="btn-group d-flex" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    var isActive = ThemeSvc.Theme == mode;
                    <button type="button"
                            class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => ThemeSvc.Theme = mode">
                        @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="accent-color">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" id="accent-color" class="form-control form-control-color"
                       value="@ThemeSvc.AccentColor"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@ThemeSvc.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mb-0">
            <strong>Current:</strong> @ThemeSvc.Theme mode, accent @ThemeSvc.AccentColor
            <br/>
            <small>Changes apply instantly to all components (check the header indicator).</small>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

